function check(input, actual, expected) {
  const [nums] = input;
  const ones = nums.filter(v => v === 1).length;
  const zeros = nums.length - ones;
  if (ones === zeros) return actual === -1;
  const majority = ones > zeros ? 1 : 0;
  return Number.isInteger(actual) && actual >= 0 && actual < nums.length && nums[actual] === majority;
}

