function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 5 || nums.length > 100000) return 'nums needs 5 to 10^5 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Every value of nums is 0 or 1.';
  return null;
}

