function adapt(input, solve, kit) {
  const [nums] = input;
  const n = nums.length;
  const limit = 2 * n;
  let calls = 0;
  // Like LeetCode's ArrayReader: the values are visible only through query() answers.
  const reader = {
    length() {
      return n;
    },
    query(a, b, c, d) {
      const picks = [a, b, c, d];
      if (picks.some(i => !Number.isInteger(i))) throw new Error('query needs four whole-number indices.');
      if (!(0 <= a && a < b && b < c && c < d && d < n)) throw new Error(`query(${a}, ${b}, ${c}, ${d}) needs 0 <= a < b < c < d < ${n}.`);
      calls++;
      if (calls > limit) throw new Error(`query was called more than 2 * n = ${limit} times.`);
      const ones = picks.reduce((sum, i) => sum + nums[i], 0);
      return ones === 0 || ones === 4 ? 4 : ones === 2 ? 0 : 2;
    },
  };
  const result = solve(reader);
  if (!Number.isInteger(result)) throw new Error('Return an index of the majority value, or -1.');
  return result;
}

