function guessMajority(reader) {
  const n = reader.length();
  const sameAsFirst = new Array(n).fill(true);
  const base = reader.query(0, 1, 2, 3);
  const pivot = reader.query(1, 2, 3, 4);

  sameAsFirst[1] = reader.query(0, 2, 3, 4) === pivot;
  sameAsFirst[2] = reader.query(0, 1, 3, 4) === pivot;
  sameAsFirst[3] = reader.query(0, 1, 2, 4) === pivot;
  sameAsFirst[4] = pivot === base;
  for (let i = 5; i < n; i++) {
    sameAsFirst[i] = reader.query(1, 2, 3, i) === base;
  }

  let sameCount = 0;
  let otherIndex = -1;
  for (let i = 0; i < n; i++) {
    if (sameAsFirst[i]) {
      sameCount++;
    } else {
      otherIndex = i;
    }
  }
  const otherCount = n - sameCount;
  if (sameCount > otherCount) {
    return 0;
  }
  if (otherCount > sameCount) {
    return otherIndex;
  }
  return -1;
}

