function guessMajority(reader) {
  // Compare every index i with index 0 directly: take three helper indices that are neither 0 nor i,
  // and ask about {0, helpers} and {i, helpers}. The answers match exactly when nums[0] === nums[i].
  const n = reader.length();
  const ask = (indices) => {
    const sorted = [...indices].sort((x, y) => x - y);
    return reader.query(sorted[0], sorted[1], sorted[2], sorted[3]);
  };
  const groups = [[0], []];
  for (let i = 1; i < n; i++) {
    const helpers = [];
    for (let j = 1; helpers.length < 3; j++) if (j !== i) helpers.push(j);
    const same = ask([0, ...helpers]) === ask([i, ...helpers]);
    groups[same ? 0 : 1].push(i);
  }
  if (groups[0].length === groups[1].length) return -1;
  const bigger = groups[0].length > groups[1].length ? groups[0] : groups[1];
  return Math.min(...bigger);
}

