function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 5 + Math.floor(rand() * 10);
  const roll = rand();
  if (roll < 0.25 && n % 2 === 0) {
    // An exact tie: half zeros, half ones, shuffled.
    const nums = Array.from({ length: n }, (_, i) => (i < n / 2 ? 0 : 1));
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    return [nums];
  }
  const chance = roll < 0.5 ? 0.5 : 0.1 + rand() * 0.8;
  return [Array.from({ length: n }, () => (rand() < chance ? 1 : 0))];
}
